mapper.delete:
-- 사용자 가족 기본정보 목록을 교체 저장하기 위해 기존 목록을 삭제한다.
DELETE FROM family_members
WHERE user_id = #{userId}

-- 사용자 간단 인터뷰 응답을 전체 교체 저장하기 위해 기존 응답을 삭제한다.
DELETE FROM member_interview_responses
WHERE member_user_id = #{userId}

-- 사용자 서류별 입력값을 전체 교체 저장하기 위해 기존 값을 삭제한다.
DELETE FROM member_document_input_values
WHERE user_id = #{userId}
